from largepanel_core import *
import shutil,hashlib
MAN=[];LEDGER=[]
def fig(h=8):return plt.figure(figsize=(183/25.4,h))
def details(identity,sources,meaning):return {'identity':identity,'sources':[str(p) for p in sources],'quantitative_meaning':meaning}
def finish(f,stem,title,caption,pdets,oldfigs):
 rec=export(f,stem,title,sorted(pdets),caption,sorted({p for v in pdets.values() for p in v['sources']}));rec['panel_details']=pdets;rec['previous_figures']=oldfigs;MAN.append(rec);(OUT/'work'/(stem+'_metadata.json')).write_text(json.dumps(rec,indent=2),encoding='utf-8');LEDGER.append({'new_figure':stem,'old_figures':oldfigs,'action':'Reassembled from underlying source tables','new_panel_ids':list(pdets)})
def balanced(d,genes):
 sz=d.groupby(['patient','programme']).size();m=d.groupby(['patient','programme'])[['log_'+g for g in genes]].mean();m=m.loc[sz.ge(5)].groupby('programme').mean().reindex(P).T;m.index=genes;return m

