  ax=axs[2,j];panel(ax,6+j,CN[c]+' retained CD8 sampling');u=d.groupby(['patient','time']).size().unstack().reindex(columns=['pre','post']);x=np.arange(len(u));ax.bar(x-.18,u.pre,width=.34,color=PRE);ax.bar(x+.18,u.post,width=.34,color=POST);ax.set(xticks=x,xticklabels=u.index,ylabel='Retained CD8 cells',yscale='log');ax.tick_params(axis='x',rotation=90,labelsize=6.3);p=source(u.reset_index(),'FigS1_'+c+'_sampling');dets[string.ascii_lowercase[6+j]]=details(CN[c]+' retained-cell sampling',[p,ROOT/'data'/(c+'_cells.csv.gz')],'Original retained-cell counts per patient and visit; logarithmic count axis')
