def canonical(s):
 import re
 s=re.sub(r'[^A-Z0-9]+','_',s.upper()).strip('_')
 for a,b in [('TNF_ALPHA','TNFA'),('NF_KB','NFKB'),('IL_2','IL2'),('IL_6','IL6'),('G2_M','G2M')]:s=s.replace(a,b)
 return s if s.startswith('HALLMARK_') else 'HALLMARK_'+s

