 f=fig(9.0);dets={};terms=sorted(canonical(s.split('\t')[0]) for s in (ROOT/'references/MSigDB_Hallmark_2020.gmt').read_text().splitlines());names=[s.replace('HALLMARK_','').replace('_',' ').capitalize().replace('Dna','DNA').replace('Il2','IL2').replace('Il6','IL6').replace('stat3','STAT3').replace('stat5','STAT5').replace('G2m','G2M').replace('Myc','MYC').replace('Mtorc1','MTORC1').replace('Tnfa','TNFA').replace('nfkb','NFKB').replace('E2f','E2F').replace('Kras','KRAS').replace('P53','p53').replace('Pi3k','PI3K').replace('Tgf','TGF').replace('Uv','UV').replace('Wnt','WNT').replace('Notch','NOTCH') for s in terms]
 for j,c in enumerate(CO):
  gs=old(c+'_Hallmark_GSEA').set_index('Term');w=gs.reindex(terms)[['NES']];w.index=names;w.columns=[CN[c]];ax=f.add_axes([.34+j*.24,.365,.14,.58]);panel(ax,j,CN[c]+' full Hallmark family');im=heat(ax,w,v=3,ylabels=j==0);ax.tick_params(axis='y',labelsize=6.7);ax.tick_params(axis='x',rotation=0,labelsize=7)
