  term='HALLMARK_INTERFERON_ALPHA_RESPONSE';rank=pd.read_csv(ROOT/'results'/(c+'_Wald_ranking.csv'),index_col=0).iloc[:,0];gmt={canonical(line.split('\t')[0]):line.split('\t')[2:] for line in (ROOT/'references/MSigDB_Hallmark_2020.gmt').read_text().splitlines()};hit=rank.index.isin(gmt[term]);weights=np.abs(rank.to_numpy());running=np.cumsum(np.where(hit,weights/max(weights[hit].sum(),1e-12),-1/max((~hit).sum(),1)));x=np.arange(len(rank))/max(len(rank)-1,1)
